def calc(t, d):
    P=t["nmck"]*(1-d); C=sum(t["cost"].values()); L=t["log"]
    fin=(C+L)*RATE*t["days"]/365; oth=P*OTHER
    pre=P-C-L-fin-oth; tax=max(0,pre)*0.15
    return dict(P=P,gp=P-C-L,gm=(P-C-L)/P,net=pre-tax,nm=(pre-tax)/P)
def breakeven(t):
    lo,hi=0.0,0.99
    for _ in range(60):
        m=(lo+hi)/2
        if calc(t,m)["net"]>0: lo=m
        else: hi=m
    return lo
if __name__=="__main__":
    out=[]
    for t in T:
        r={k:calc(t,d) for k,d in zip(("best","base","worst"),t["disc"])}
        r0=calc(t,0.0); be=breakeven(t)
        C=sum(t["cost"].values())
        out.append(dict(t=t,r=r,r0=r0,be=be,C=C))
        extra=""
        if "tons" in t:
            t2=dict(t); t2["cost"]={"x":t["tons"]*(SALT+LAST)}; extra=f" | с посл. милей +{LAST}: база {calc(t2,t['disc'][1])['net']:,.0f}, безуб. {breakeven(t2)*100:.0f}%"
        print(f"{t['id']} {t['name']}: НМЦК {t['nmck']:,} себест {C:,}+лог {t['log']:,} | при НМЦК: ВМ {r0['gm']*100:.0f}% прибыль {r0['net']:,.0f} | база (−{t['disc'][1]*100:.0f}%): цена {r['base']['P']:,.0f} ВМ {r['base']['gm']*100:.0f}% прибыль {r['base']['net']:,.0f} | худший (−{t['disc'][2]*100:.0f}%): {r['worst']['net']:,.0f} | безубыточное снижение {be*100:.0f}%"+extra)
    if len(sys.argv)>1: json.dump(out,open(sys.argv[1],"w"),ensure_ascii=False,default=float,indent=1)
